      htmlFor={inputId}
      hint={hint ? <span id={hintId}>{hint}</span> : undefined}
      error={error ? <span id={errorId}>{error}</span> : undefined}
      required={required}
    >
      <input
        ref={ref}
        id={inputId}
        className={`text-input ${className}`.trim()}
        required={required}
        aria-invalid={error ? true : undefined}
        aria-describedby={describedBy || undefined}
        {...props}
      />
    </Field>
  );
});

