import type { Bookmark } from "../../lib/api";
import { Button, IconPlaceholder } from "../../components";

export interface BookmarkCardProps {
  bookmark: Bookmark;
  onOpen: (bookmark: Bookmark) => void;
}

function displayDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(new Date(value));
}

export function BookmarkCard({ bookmark, onOpen }: BookmarkCardProps) {
  return (
    <article className="bookmark-card" aria-label={bookmark.title}>
      <div className="bookmark-card__icon">
        {bookmark.iconUrl ? (
          <img src={bookmark.iconUrl} alt={`Site icon for ${bookmark.title}`} width="40" height="40" />
        ) : (
          <IconPlaceholder label={`No site icon for ${bookmark.title}`} />
        )}
      </div>
      <div className="bookmark-card__content">
        <div className="bookmark-card__heading">
          <Button variant="quiet" className="bookmark-card__title" onClick={() => onOpen(bookmark)}>
            {bookmark.title}
          </Button>
          <div className="bookmark-card__badges" aria-label="Bookmark states">
            {bookmark.favorite ? <span className="bookmark-badge">★ Favorite</span> : null}
            {bookmark.unread ? <span className="bookmark-badge">Read Later</span> : null}
          </div>
        </div>
        <p className="bookmark-card__address" title={bookmark.address}>
          {bookmark.address}
        </p>
        {bookmark.description ? (
          <p className="bookmark-card__description">{bookmark.description}</p>
        ) : null}
        <div className="bookmark-card__meta">
          {bookmark.tags.length ? (
            <ul className="tag-list" aria-label="Tags">
              {bookmark.tags.map((tag) => (
                <li key={tag.id}>{tag.name}</li>
              ))}
            </ul>
          ) : (
            <span>No tags</span>
          )}
          <span>Saved {displayDate(bookmark.createdAt)}</span>
        </div>
      </div>
      <a
        className="bookmark-card__open"
        href={bookmark.address}
        target="_blank"
        rel="noopener noreferrer"
        aria-label={`Open destination for ${bookmark.title}`}
      >
        Open <span aria-hidden="true">↗</span>
      </a>
    </article>
  );
}

import { Button, Dialog, IconPlaceholder, Status } from "../../components";
import type { Bookmark } from "../../lib/api";

export interface BookmarkDetailProps {
  bookmark: Bookmark;
  onClose: () => void;
  editing?: boolean;
}

function displayDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(value));
}

export function BookmarkDetail({ bookmark, onClose, editing = false }: BookmarkDetailProps) {
  return (
    <Dialog
      open
      title={bookmark.title}
      description={bookmark.description || "No description has been added."}
      onClose={onClose}
      footer={
        <>
          <Button variant="quiet" onClick={onClose}>Close</Button>
          <a
            className="button button--primary button--medium"
            href={bookmark.address}
            target="_blank"
            rel="noopener noreferrer"
          >
            <span>Open destination ↗</span>
          </a>
        </>
      }
    >
      <div className="bookmark-detail">
        {editing ? <Status tone="warning">This bookmark is ready to edit.</Status> : null}
        <div className="bookmark-detail__identity">
          {bookmark.iconUrl ? (
            <img src={bookmark.iconUrl} alt={`Site icon for ${bookmark.title}`} width="48" height="48" />
          ) : (
            <IconPlaceholder label={`No site icon for ${bookmark.title}`} size="large" />
          )}
          <p>{bookmark.address}</p>
        </div>
        <dl className="bookmark-detail__facts">
          <div>
            <dt>Reading</dt>
            <dd>{bookmark.unread ? "Read Later" : "Read"}</dd>
          </div>
          <div>
            <dt>Favorite</dt>
            <dd>{bookmark.favorite ? "Yes" : "No"}</dd>
          </div>
