import { type FormEvent, useEffect, useState } from "react";
import { parseSearchQuery } from "../../../shared/search/parser";
import { Button } from "../../components";
import type { TagSummary } from "../../lib/api";
import type { ViewState } from "../../lib/view-state";
import { FilterPanel } from "./FilterPanel";

export interface SearchControlsProps {
  view: ViewState;
  tags: TagSummary[];
  total: number;
  onChange: (next: ViewState) => void;
}

export function SearchControls({ view, tags, total, onChange }: SearchControlsProps) {
  const [query, setQuery] = useState(view.query);
  const [showHelp, setShowHelp] = useState(false);
  const parsed = parseSearchQuery(query);

  useEffect(() => setQuery(view.query), [view.query]);

  function submit(event: FormEvent) {
    event.preventDefault();
    if (!parsed.ok) return;
    onChange({ ...view, query: query.trim(), cursor: null, savedViewId: null });
  }

  function clear() {
    setQuery("");
    onChange({
      ...view,
      query: "",
      tags: [],
      favorite: null,
      unread: null,
      cursor: null,
      savedViewId: null,
    });
  }

  const hasCriteria = Boolean(
    view.query || view.tags.length || view.favorite !== null || view.unread !== null,
  );
  const scopeLabel =
    view.scope === "active" ? "active" : view.scope === "read_later" ? "Read Later" : "archived";

  return (
    <section className="search-controls" aria-label="Search and filters">
      <form className="search-form" role="search" onSubmit={submit}>
        <label htmlFor="bookmark-search">Search bookmarks</label>
        <div className="search-form__row">
          <input
            id="bookmark-search"
            type="search"
            value={query}
            placeholder={'Try #news, "exact phrase", AND or OR'}
            aria-invalid={!parsed.ok || undefined}
            aria-describedby={!parsed.ok ? "search-syntax-error" : "search-guidance"}
            onChange={(event) => setQuery(event.currentTarget.value)}
          />
          <Button type="submit" variant="primary" disabled={!parsed.ok}>
            Search
          </Button>
          <Button onClick={() => setShowHelp((current) => !current)} aria-expanded={showHelp}>
            Search syntax help
          </Button>
        </div>
        {!parsed.ok ? (
          <p id="search-syntax-error" className="search-error" role="alert">
            {parsed.error.message} {parsed.error.hint}.
          </p>
        ) : (
          <p id="search-guidance" className="search-guidance">
            Ordinary terms all match. Use #tag, quotes, AND, or OR for precision.
          </p>
        )}
        {showHelp ? (
          <div className="search-help">
            <p>
              Use <code>#news</code> for an exact tag and <code>#&quot;machine learning&quot;</code>{" "}
              for a multiword tag.
            </p>
            <p>
              Put an <strong>exact phrase</strong> in quotes. Adjacent terms act like AND; OR
              accepts either side.
            </p>
          </div>
        ) : null}
      </form>

      <FilterPanel view={view} tags={tags} onChange={onChange} />

      <div className="search-summary" aria-live="polite">
        <span>
          {total === 0 && hasCriteria
            ? `No ${scopeLabel} bookmarks match these criteria.`
            : `${total} bookmark${total === 1 ? "" : "s"} in this view.`}
        </span>
        {hasCriteria ? (
          <Button variant="quiet" size="small" onClick={clear}>
            Clear search and filters
          </Button>
        ) : null}
      </div>
    </section>
  );
}
import type { Scope, SortOrder, TagSummary } from "../../lib/api";
import type { ViewState } from "../../lib/view-state";

export interface FilterPanelProps {
  view: ViewState;
  tags: TagSummary[];
  onChange: (next: ViewState) => void;
}

const sorts: Array<{ value: SortOrder; label: string }> = [
  { value: "created_desc", label: "Newest saved" },
  { value: "created_asc", label: "Oldest saved" },
  { value: "updated_desc", label: "Recently modified" },
  { value: "title_asc", label: "Title" },
];

function nullableBoolean(value: string): boolean | null {
  return value === "true" ? true : value === "false" ? false : null;
}

function withReset(view: ViewState, changes: Partial<ViewState>): ViewState {
  return { ...view, ...changes, cursor: null, savedViewId: null };
}

export function FilterPanel({ view, tags, onChange }: FilterPanelProps) {
  function toggleTag(name: string, selected: boolean) {
    const next = selected
      ? [...view.tags, name]
      : view.tags.filter((candidate) => candidate !== name);
    onChange(withReset(view, { tags: Array.from(new Set(next)) }));
  }

  return (
    <div className="filter-panel">
      {tags.length ? (
        <fieldset className="filter-group filter-group--tags">
          <legend>Tags — all selected are required</legend>
          <div className="filter-tags">
            {tags.map((tag) => (
              <label key={tag.id}>
                <input
                  type="checkbox"
                  checked={view.tags.includes(tag.name)}
                  onChange={(event) => toggleTag(tag.name, event.currentTarget.checked)}
                />
                <span>{tag.name}</span>
                <small>{tag.activeBookmarkCount}</small>
              </label>
            ))}
          </div>
        </fieldset>
      ) : null}

      <div className="filter-selects">
        <label>
          <span>Favorite filter</span>
          <select
            value={view.favorite === null ? "any" : String(view.favorite)}
            onChange={(event) =>
              onChange(withReset(view, { favorite: nullableBoolean(event.currentTarget.value) }))
            }
          >
            <option value="any">Any</option>
            <option value="true">Favorites only</option>
            <option value="false">Not favorites</option>
          </select>
        </label>

        {view.scope !== ("read_later" satisfies Scope) ? (
          <label>
            <span>Reading filter</span>
            <select
              value={view.unread === null ? "any" : String(view.unread)}
              onChange={(event) =>
                onChange(withReset(view, { unread: nullableBoolean(event.currentTarget.value) }))
              }
            >
              <option value="any">Any</option>
              <option value="true">Read Later</option>
              <option value="false">Read</option>
            </select>
          </label>
        ) : null}

        <label>
          <span>Sort bookmarks</span>
          <select
            value={view.sort}
            onChange={(event) =>
              onChange(withReset(view, { sort: event.currentTarget.value as SortOrder }))
            }
          >
            {sorts.map((sort) => (
              <option key={sort.value} value={sort.value}>
                {sort.label}
              </option>
            ))}
          </select>
        </label>
      </div>
    </div>
  );
}
                {collection.nextCursor ? (
                  <div className="collection-pagination">
                    <Button onClick={() => updateView({ ...view, cursor: collection.nextCursor })}>
                      Load more results
                    </Button>
                  </div>
                ) : null}
              </>
            ) : (
              <EmptyState
                title={hasCriteria ? "No bookmarks match this view" : copy.emptyTitle}
                description={
                  hasCriteria
                    ? "Try removing a filter or simplifying the search expression."
                    : copy.emptyDescription
                }
                icon={<BrandMark />}
                action={
                  hasCriteria ? (
                    <Button
                      onClick={() =>
                        updateView({
                          ...view,
                          query: "",
                          tags: [],
                          favorite: null,
                          unread: null,
                          cursor: null,
                        })
                      }
                    >
                      Clear search and filters
                    </Button>
                  ) : view.scope === "active" ? (
                    <Button variant="primary" onClick={() => setCaptureOpen(true)}>
                      Add your first bookmark
