import { Button, Dialog, IconPlaceholder, Status } from "../../components";
import type { Bookmark } from "../../lib/api";

export interface BookmarkDetailProps {
  bookmark: Bookmark;
  onClose: () => void;
  editing?: boolean;
}

function displayDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(value));
}

export function BookmarkDetail({ bookmark, onClose, editing = false }: BookmarkDetailProps) {
  return (
    <Dialog
      open
      title={bookmark.title}
      description={bookmark.description || "No description has been added."}
      onClose={onClose}
      footer={
        <>
          <Button variant="quiet" onClick={onClose}>
            Close
          </Button>
          <a
            className="button button--primary button--medium"
            href={bookmark.address}
            target="_blank"
            rel="noopener noreferrer"
          >
            <span>Open destination ↗</span>
          </a>
        </>
      }
    >
      <div className="bookmark-detail">
        {editing ? <Status tone="warning">This bookmark is ready to edit.</Status> : null}
        <div className="bookmark-detail__identity">
          {bookmark.iconUrl ? (
            <img
              src={bookmark.iconUrl}
              alt={`Site icon for ${bookmark.title}`}
              width="48"
              height="48"
            />
          ) : (
            <IconPlaceholder label={`No site icon for ${bookmark.title}`} size="large" />
          )}
          <p>{bookmark.address}</p>
        </div>
        <dl className="bookmark-detail__facts">
          <div>
            <dt>Reading</dt>
            <dd>{bookmark.unread ? "Read Later" : "Read"}</dd>
          </div>
          <div>
            <dt>Favorite</dt>
            <dd>{bookmark.favorite ? "Yes" : "No"}</dd>
          </div>
          <div>
            <dt>Created</dt>
            <dd>{displayDate(bookmark.createdAt)}</dd>
          </div>
          <div>
            <dt>Updated</dt>
            <dd>{displayDate(bookmark.updatedAt)}</dd>
          </div>
        </dl>
        {bookmark.tags.length ? (
          <ul className="tag-list" aria-label="Tags">
            {bookmark.tags.map((tag) => (
              <li key={tag.id}>{tag.name}</li>
            ))}
          </ul>
        ) : null}
      </div>
    </Dialog>
  );
}
import { Component, type ErrorInfo, type ReactNode, useEffect, useRef, useState } from "react";
import { Button, Dialog, EmptyState, Status } from "../components";
import { BookmarkDetail } from "../features/bookmarks/BookmarkDetail";
import { BookmarkList } from "../features/bookmarks/BookmarkList";
import { CaptureForm } from "../features/capture/CaptureForm";
import { SearchControls } from "../features/search/SearchControls";
import { api, type Bookmark, type BookmarkPage, type Scope, type TagSummary } from "../lib/api";
import {
  readViewState,
  subscribeToViewState,
  type ViewState,
  viewStateHref,
  withScope,
  writeViewState,
} from "../lib/view-state";

type StartupState = "loading" | "ready" | "error";

const scopeCopy = {
  active: {
    label: "Bookmarks",
    eyebrow: "Your collection",
    title: "A calmer place for the links worth keeping.",
    emptyTitle: "Your bookmark garden is ready",
    emptyDescription:
      "Paste a web address to save it. Page details will be gathered automatically when possible.",
  },
  read_later: {
    label: "Read later",
    eyebrow: "Reading queue",
    title: "Keep the next good read within reach.",
    emptyTitle: "Nothing waiting to be read",
    emptyDescription:
      "Bookmarks marked Read Later appear here while keeping their favorite status separate.",
  },
  archived: {
    label: "Archive",
    eyebrow: "Out of the way, not gone",
    title: "A quiet shelf for links you may need again.",
    emptyTitle: "Your archive is empty",
    emptyDescription: "Archived bookmarks will stay here with their tags and reading state intact.",
  },
} as const;

interface ErrorBoundaryState {
  failed: boolean;
}

export class AppErrorBoundary extends Component<{ children: ReactNode }, ErrorBoundaryState> {
  state: ErrorBoundaryState = { failed: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { failed: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    if (import.meta.env.DEV) console.error("Application render failed", error, info);
  }

  render() {
    if (this.state.failed) {
      return (
        <main className="fatal-state" role="alert">
          <p className="eyebrow">Something went wrong</p>
          <h1>The bookmark garden could not be displayed.</h1>
          <p>Your bookmarks have not been changed. Reload the page to try again.</p>
          <Button variant="primary" onClick={() => window.location.reload()}>
            Reload app
          </Button>
        </main>
      );
    }
    return this.props.children;
  }
}

function BrandMark() {
  return (
    <span className="brand-mark" aria-hidden="true">
      <svg viewBox="0 0 36 36" focusable="false">
        <title>Bookmark Garden</title>
        <path d="M18 31V16" />
        <path d="M18 21c-6.2 0-10-3.4-10-9 6.2 0 10 3.4 10 9Z" />
        <path d="M18 16c5.7 0 9.2-3.1 9.2-8.2C21.5 7.8 18 10.9 18 16Z" />
        <path d="M11 31h14" />
      </svg>
    </span>
  );
}

function LoadingShell() {
  return (
    <div
      className="startup-state"
      role="status"
      aria-busy="true"
      aria-label="Loading Bookmark Garden"
    >
      <BrandMark />
      <p>Preparing your collection…</p>
    </div>
  );
}

function StartupError({ onRetry }: { onRetry: () => void }) {
  return (
    <main className="fatal-state" role="alert">
      <p className="eyebrow">Unable to connect</p>
      <h1>Your bookmark collection is not available yet.</h1>
      <p>Nothing was changed. Check that the app is running, then try again.</p>
      <Button variant="primary" onClick={onRetry}>
        Try again
      </Button>
    </main>
  );
}

export function App() {
  const [startup, setStartup] = useState<StartupState>("loading");
  const [view, setView] = useState<ViewState>(() => readViewState());
  const [collection, setCollection] = useState<BookmarkPage | null>(null);
  const [collectionError, setCollectionError] = useState(false);
  const [tags, setTags] = useState<TagSummary[]>([]);
  const [readLaterCount, setReadLaterCount] = useState<number | null>(null);
  const [readingFeedback, setReadingFeedback] = useState("");
  const [captureOpen, setCaptureOpen] = useState(false);
  const [selectedBookmark, setSelectedBookmark] = useState<Bookmark | null>(null);
  const captureAddressRef = useRef<HTMLInputElement>(null);
  const readingFeedbackRef = useRef<HTMLDivElement>(null);

  useEffect(() => subscribeToViewState(setView), []);

  useEffect(() => {
    const controller = new AbortController();
    setStartup("loading");
    api
      .getHealth({ signal: controller.signal })
      .then(() => setStartup("ready"))
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) setStartup("error");
      });
    return () => controller.abort();
  }, []);

  useEffect(() => {
    if (startup !== "ready") return;
    const controller = new AbortController();
    setCollection(null);
    setCollectionError(false);
    api
      .listBookmarks(
        {
          scope: view.scope,
          query: view.query,
          tags: view.tags,
          favorite: view.favorite,
          unread: view.unread,
          sort: view.sort,
          ...(view.cursor ? { cursor: view.cursor } : {}),
        },
        { signal: controller.signal },
      )
      .then(setCollection)
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) {
          setCollectionError(true);
        }
      });
    return () => controller.abort();
  }, [startup, view]);

  useEffect(() => {
    if (startup !== "ready") return;
    const controller = new AbortController();
    api
      .listTags({ signal: controller.signal })
      .then(setTags)
      .catch(() => setTags([]));
    return () => controller.abort();
  }, [startup]);

  useEffect(() => {
    if (startup !== "ready") return;
    const controller = new AbortController();
    api
      .listBookmarks({ scope: "read_later", limit: 1 }, { signal: controller.signal })
      .then((page) => setReadLaterCount(page.total))
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) {
          setReadLaterCount(null);
        }
      });
    return () => controller.abort();
  }, [startup]);

  useEffect(() => {
    if (startup !== "ready" || view.bookmarkId === null) return;
    const fromPage = collection?.items.find((bookmark) => bookmark.id === view.bookmarkId);
    if (fromPage) {
      setSelectedBookmark(fromPage);
      return;
    }
    const controller = new AbortController();
    api
      .getBookmark(view.bookmarkId, { signal: controller.signal })
      .then(setSelectedBookmark)
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) {
          setSelectedBookmark(null);
        }
      });
    return () => controller.abort();
  }, [collection, startup, view.bookmarkId]);

  function navigate(scope: ViewState["scope"]) {
    setSelectedBookmark(null);
    const next = withScope(view, scope);
    writeViewState(next);
  }

  function updateView(next: ViewState) {
    setSelectedBookmark(null);
    writeViewState({ ...next, bookmarkId: null, editing: false });
  }

  function openBookmark(bookmark: Bookmark, editing = false) {
    setSelectedBookmark(bookmark);
    writeViewState({ ...view, bookmarkId: bookmark.id, editing });
  }

  function closeBookmark() {
    setSelectedBookmark(null);
    writeViewState({ ...view, bookmarkId: null, editing: false }, "replace");
  }

  function handleSaved(bookmark: Bookmark) {
    setCaptureOpen(false);
    if (view.scope === "active") {
      setCollection((current) =>
        current
          ? { ...current, items: [bookmark, ...current.items], total: current.total + 1 }
          : current,
      );
    }
    if (bookmark.unread && !bookmark.archived) {
      setReadLaterCount((current) => (current === null ? 1 : current + 1));
    }
    openBookmark(bookmark);
  }

  async function handleToggleReadLater(bookmark: Bookmark, unread: boolean) {
    const updated = await api.updateBookmark(bookmark.id, { unread });
    setCollection((current) => {
      if (!current) return current;
      if (view.scope === "read_later" && !updated.unread) {
        return {
          ...current,
          items: current.items.filter((item) => item.id !== bookmark.id),
          total: Math.max(0, current.total - 1),
        };
      }
      return {
        ...current,
        items: current.items.map((item) => (item.id === bookmark.id ? updated : item)),
      };
    });
    setSelectedBookmark((current) => (current?.id === bookmark.id ? updated : current));
    setReadLaterCount((current) => {
      if (current === null) return unread ? 1 : 0;
      return Math.max(0, current + (unread ? 1 : -1));
    });
    setReadingFeedback(
      unread
        ? `${bookmark.title} was added to Read Later.`
        : `${bookmark.title} was marked as read.`,
    );
    if (view.scope === "read_later" && !unread) {
      window.requestAnimationFrame(() => readingFeedbackRef.current?.focus());
    }
  }

  function handleDuplicate(bookmarkId: number, scope?: Scope) {
    setCaptureOpen(false);
    const next = {
      ...view,
      scope: scope ?? view.scope,
      bookmarkId,
      editing: true,
      cursor: null,
    };
    writeViewState(next);
  }

  if (startup === "loading") return <LoadingShell />;
  if (startup === "error") return <StartupError onRetry={() => window.location.reload()} />;

  const copy = scopeCopy[view.scope];
  const hasCriteria = Boolean(
    view.query || view.tags.length || view.favorite !== null || view.unread !== null,
  );

  return (
    <div
      className="app-shell"
      data-harness-ready={collection !== null || collectionError ? "true" : undefined}
    >
      <a className="skip-link" href="#main-content">
        Skip to collection
      </a>
      <header className="site-header">
        <a
          className="brand"
          href={viewStateHref(withScope(view, "active"))}
          onClick={(event) => {
            event.preventDefault();
            navigate("active");
          }}
        >
          <BrandMark />
          <span>
            <strong>Bookmark Garden</strong>
            <small>Links, thoughtfully kept</small>
          </span>
        </a>
        <div className="header-actions">
          <Button variant="primary" onClick={() => setCaptureOpen(true)}>
            <span aria-hidden="true">＋</span> Add bookmark
          </Button>
        </div>
      </header>

      <div className="app-layout">
        <aside className="sidebar" aria-label="Collection navigation">
          <nav>
            <p className="nav-label">Library</p>
            <ul className="nav-list">
              {(Object.keys(scopeCopy) as ViewState["scope"][]).map((scope) => (
                <li key={scope}>
                  <a
                    href={viewStateHref(withScope(view, scope))}
                    className={view.scope === scope ? "nav-link nav-link--active" : "nav-link"}
                    aria-current={view.scope === scope ? "page" : undefined}
                    onClick={(event) => {
                      event.preventDefault();
                      navigate(scope);
                    }}
                  >
                    <span>{scopeCopy[scope].label}</span>
                    {scope === "read_later" && readLaterCount !== null ? (
                      <span className="nav-count">
                        <span aria-hidden="true">{readLaterCount}</span>
                        <span className="visually-hidden">
                          {readLaterCount} unread bookmark{readLaterCount === 1 ? "" : "s"}
                        </span>
                      </span>
                    ) : null}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
          <div className="sidebar-note">
            <span aria-hidden="true">✦</span>
            <p>Saved views will keep your favorite searches close at hand.</p>
          </div>
        </aside>

        <main id="main-content" className="main-content" tabIndex={-1}>
          <div
            ref={readingFeedbackRef}
            className="reading-feedback"
            role="status"
            aria-label="Reading list update"
            aria-live="polite"
            aria-atomic="true"
            tabIndex={-1}
          >
            {readingFeedback}
          </div>
          <section className="page-heading">
            <div>
              <p className="eyebrow">{copy.eyebrow}</p>
              <h1>{copy.title}</h1>
            </div>
            <Status live="off">Ready for your links</Status>
          </section>

          <SearchControls
            view={view}
            tags={tags}
            total={collection?.total ?? 0}
            onChange={updateView}
          />

          <section className="collection-panel" aria-labelledby="collection-title">
            <div className="collection-panel__header">
              <div>
                <p className="eyebrow">Current view</p>
                <h2 id="collection-title">{copy.label}</h2>
              </div>
              <span className="result-count">
                {collection
                  ? `${collection.total} bookmark${collection.total === 1 ? "" : "s"}`
                  : ""}
              </span>
            </div>
            {collectionError ? (
              <EmptyState
                title="This collection could not be loaded"
                description="Your bookmarks have not been changed. Reload the page to try again."
                action={<Button onClick={() => window.location.reload()}>Reload</Button>}
              />
            ) : collection === null ? (
              <div className="collection-loading" role="status" aria-live="polite">
                Loading bookmarks…
              </div>
            ) : collection.items.length ? (
              <>
                <BookmarkList
                  bookmarks={collection.items}
                  onOpen={openBookmark}
                  onToggleReadLater={view.scope === "archived" ? undefined : handleToggleReadLater}
                />
                {collection.nextCursor ? (
                  <div className="collection-pagination">
                    <Button onClick={() => updateView({ ...view, cursor: collection.nextCursor })}>
                      Load more results
                    </Button>
                  </div>
                ) : null}
              </>
            ) : (
              <EmptyState
                title={hasCriteria ? "No bookmarks match this view" : copy.emptyTitle}
                description={
                  hasCriteria
                    ? "Try removing a filter or simplifying the search expression."
                    : copy.emptyDescription
                }
                icon={<BrandMark />}
                action={
                  hasCriteria ? (
                    <Button
                      onClick={() =>
                        updateView({
                          ...view,
                          query: "",
                          tags: [],
                          favorite: null,
                          unread: null,
                          cursor: null,
                        })
                      }
                    >
                      Clear search and filters
                    </Button>
                  ) : view.scope === "active" ? (
                    <Button variant="primary" onClick={() => setCaptureOpen(true)}>
                      Add your first bookmark
                    </Button>
                  ) : view.scope === "read_later" ? (
                    <Button onClick={() => navigate("active")}>Browse bookmarks</Button>
                  ) : undefined
                }
              />
            )}
          </section>
        </main>
      </div>

      <footer className="site-footer">
        <p>Your collection stays on this app installation.</p>
      </footer>

      <Dialog
        open={captureOpen}
        title="Save a bookmark"
        description="Paste an address and save right away. Page details will arrive automatically when available."
        onClose={() => setCaptureOpen(false)}
        initialFocusRef={captureAddressRef}
      >
        <CaptureForm
          addressInputRef={captureAddressRef}
          onSaved={handleSaved}
          onDuplicate={handleDuplicate}
          onCancel={() => setCaptureOpen(false)}
        />
      </Dialog>

      {selectedBookmark ? (
        <BookmarkDetail
          bookmark={selectedBookmark}
          editing={view.editing}
          onClose={closeBookmark}
        />
      ) : null}
    </div>
  );
}
import { useState } from "react";
import { Button, IconPlaceholder } from "../../components";
import type { Bookmark } from "../../lib/api";

export interface BookmarkCardProps {
  bookmark: Bookmark;
  onOpen: (bookmark: Bookmark) => void;
  onToggleReadLater?: ((bookmark: Bookmark, unread: boolean) => Promise<void> | void) | undefined;
}

function displayDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(new Date(value));
}

export function BookmarkCard({ bookmark, onOpen, onToggleReadLater }: BookmarkCardProps) {
  const [updatingReadingState, setUpdatingReadingState] = useState(false);
  const [readingError, setReadingError] = useState<string | null>(null);

  async function toggleReadLater() {
    if (!onToggleReadLater) return;
    setUpdatingReadingState(true);
    setReadingError(null);
    try {
      await onToggleReadLater(bookmark, !bookmark.unread);
    } catch {
      setReadingError("Reading state could not be changed. Please try again.");
    } finally {
      setUpdatingReadingState(false);
    }
  }

  return (
    <article className="bookmark-card" aria-label={bookmark.title}>
      <div className="bookmark-card__icon">
        {bookmark.iconUrl ? (
          <img
            src={bookmark.iconUrl}
            alt={`Site icon for ${bookmark.title}`}
            width="40"
            height="40"
          />
        ) : (
          <IconPlaceholder label={`No site icon for ${bookmark.title}`} />
        )}
      </div>
      <div className="bookmark-card__content">
        <div className="bookmark-card__heading">
          <Button variant="quiet" className="bookmark-card__title" onClick={() => onOpen(bookmark)}>
            {bookmark.title}
          </Button>
          <div className="bookmark-card__badges">
            {bookmark.favorite ? <span className="bookmark-badge">★ Favorite</span> : null}
            {bookmark.unread ? <span className="bookmark-badge">Read Later</span> : null}
          </div>
        </div>
        <p className="bookmark-card__address" title={bookmark.address}>
          {bookmark.address}
        </p>
        {bookmark.description ? (
          <p className="bookmark-card__description">{bookmark.description}</p>
        ) : null}
        <div className="bookmark-card__meta">
          {bookmark.tags.length ? (
            <ul className="tag-list" aria-label="Tags">
              {bookmark.tags.map((tag) => (
                <li key={tag.id}>{tag.name}</li>
              ))}
            </ul>
          ) : (
            <span>No tags</span>
          )}
          <span>Saved {displayDate(bookmark.createdAt)}</span>
        </div>
      </div>
      <div className="bookmark-card__actions">
        {onToggleReadLater ? (
          <Button
            variant="quiet"
            size="small"
            busy={updatingReadingState}
            busyLabel="Updating…"
            aria-label={
              bookmark.unread
                ? `Mark ${bookmark.title} as read`
                : `Add ${bookmark.title} to Read Later`
            }
            onClick={toggleReadLater}
          >
            {bookmark.unread ? "Mark read" : "Read Later"}
          </Button>
        ) : null}
        <a
          className="bookmark-card__open"
          href={bookmark.address}
          target="_blank"
          rel="noopener noreferrer"
          aria-label={`Open destination for ${bookmark.title}`}
        >
          Open <span aria-hidden="true">↗</span>
        </a>
        {readingError ? (
          <span className="bookmark-card__error" role="alert">
            {readingError}
          </span>
        ) : null}
      </div>
    </article>
  );
}
.bookmark-card__title {
  min-height: auto;
  justify-content: start;
  border-radius: 0.25rem;
  padding: 0;
  color: var(--ink-950);
  font-family: var(--font-display);
  font-size: 1.25rem;
  text-align: left;
}

.bookmark-card__badges {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.bookmark-badge,
.tag-list li {
  border-radius: 999px;
  padding: 0.2rem 0.55rem;
  background: var(--leaf-100);
  color: var(--leaf-700);
  font-size: 0.75rem;
  font-weight: 700;
}

.bookmark-card__address {
  overflow: hidden;
  margin: 0.35rem 0 0;
  color: var(--ink-600);
  font-size: 0.82rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark-card__description {
  display: -webkit-box;
  overflow: hidden;
  margin: 0.65rem 0 0;
  color: var(--ink-800);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.bookmark-card__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: 0.8rem;
  color: var(--ink-600);
  font-size: 0.76rem;
}

.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bookmark-card__open {
  border-radius: 0.25rem;
  font-size: 0.84rem;
  font-weight: 750;
  text-decoration: none;
  white-space: nowrap;
}

.bookmark-card__actions {
  display: flex;
  align-items: center;
  justify-content: end;
  gap: 0.45rem;
}

.bookmark-card__error {
  grid-column: 1 / -1;
  color: var(--danger-700);
  font-size: 0.76rem;
  font-weight: 650;
}

.bookmark-card__open:hover {
  text-decoration: underline;
}

.bookmark-detail {
  display: grid;
  gap: 1.2rem;
}

.bookmark-detail__identity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.8rem;
}

.bookmark-detail__identity p {
  overflow-wrap: anywhere;
  margin: 0;
  color: var(--ink-600);
}

.bookmark-detail__facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
  margin: 0;
}

.bookmark-detail__facts div {
  padding: 0.7rem;
  border-radius: var(--radius-small);
  background: var(--paper);
}

.bookmark-detail__facts dt {
  color: var(--ink-600);
  font-size: 0.72rem;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.bookmark-detail__facts dd {
  margin: 0.2rem 0 0;
}

.startup-state,
.fatal-state {
  display: grid;
  min-height: 100vh;
  padding: 2rem;
  place-items: center;
  align-content: center;
  text-align: center;
}

.startup-state .brand-mark {
  width: 4.5rem;
  height: 4.5rem;
  animation: breathe 1.7s ease-in-out infinite;
}

.startup-state p,
.fatal-state > p:not(.eyebrow) {
  max-width: 34rem;
  color: var(--ink-600);
}

.fatal-state .button {
  margin-top: 1rem;
}

.site-footer {
  padding: 1rem clamp(1rem, 4vw, 3.5rem);
  border-top: 1px solid var(--line);
  color: var(--ink-600);
  font-size: 0.75rem;
  text-align: right;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes breathe {
  50% {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(63, 118, 86, 0.18);
  }
}

@media (max-width: 760px) {
  .site-header {
    min-height: 4.5rem;
  }

  .brand small {
    display: none;
  }

  .header-actions .button span:last-child {
    font-size: 0;
  }

  .header-actions .button span:last-child::after {
    font-size: 0.86rem;
    content: "Add";
  }

  .app-layout {
    display: block;
  }

  .sidebar {
    display: block;
    overflow-x: auto;
    padding: 0.7rem 1rem;
    border-right: 0;
    border-bottom: 1px solid var(--line);
    scrollbar-width: none;
  }

  .sidebar::-webkit-scrollbar,
  .sidebar .nav-label,
  .sidebar-note {
    display: none;
  }

  .nav-list {
    display: flex;
    width: max-content;
  }

  .nav-link {
    min-height: 2.5rem;
    white-space: nowrap;
  }

  .nav-link--active {
    box-shadow: inset 0 -3px var(--leaf-600);
  }

  .main-content {
    padding: 1.5rem 1rem 2.5rem;
  }

  .search-form__row {
    align-items: stretch;
    flex-direction: column;
  }

  .filter-selects,
  .filter-selects label {
    width: 100%;
  }

  .page-heading {
    display: block;
  }

  .page-heading .status {
    margin-top: 1rem;
  }

  .collection-panel {
    min-height: 23rem;
    border-radius: var(--radius-medium);
  }

  .bookmark-card {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .bookmark-card__heading,
  .bookmark-card__meta {
    align-items: start;
    flex-direction: column;
  }

  .bookmark-card__actions {
    grid-column: 2;
    justify-content: start;
  }

  .site-footer {
    text-align: center;
  }
}

@media (max-width: 390px) {
  .site-header {
    padding-inline: 0.75rem;
  }

  .brand strong {
    font-size: 1rem;
  }

  .brand-mark {
    width: 2.1rem;
    height: 2.1rem;
  }

  .collection-panel__header {
    align-items: start;
    flex-direction: column;
  }

  .dialog {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto;
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
    transition-duration: 0.01ms;
  }
}

@media (prefers-contrast: more) {
  :root {
    --line: #827d70;
    --line-strong: #615d53;
  }
}

