  min-height: auto;
  justify-content: start;
  border-radius: 0.25rem;
  padding: 0;
  color: var(--ink-950);
  font-family: var(--font-display);
  font-size: 1.25rem;
  text-align: left;
}

.bookmark-card__badges {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.bookmark-badge,
.tag-list li {
  border-radius: 999px;
  padding: 0.2rem 0.55rem;
  background: var(--leaf-100);
  color: var(--leaf-700);
  font-size: 0.75rem;
  font-weight: 700;
}

.bookmark-card__address {
