  width: 4.5rem;
  height: 4.5rem;
  animation: breathe 1.7s ease-in-out infinite;
}

.startup-state p,
.fatal-state > p:not(.eyebrow) {
  max-width: 34rem;
  color: var(--ink-600);
}

.fatal-state .button {
  margin-top: 1rem;
}

.site-footer {
  padding: 1rem clamp(1rem, 4vw, 3.5rem);
  border-top: 1px solid var(--line);
  color: var(--ink-600);
  font-size: 0.75rem;
  text-align: right;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes breathe {
  50% {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(63, 118, 86, 0.18);
  }
}

@media (max-width: 760px) {
  .site-header {
    min-height: 4.5rem;
  }

  .brand small {
    display: none;
  }

  .header-actions .button span:last-child {
    font-size: 0;
  }

  .header-actions .button span:last-child::after {
    font-size: 0.86rem;
    content: "Add";
  }

  .app-layout {
    display: block;
  }

  .sidebar {
    display: block;
    overflow-x: auto;
    padding: 0.7rem 1rem;
    border-right: 0;
    border-bottom: 1px solid var(--line);
    scrollbar-width: none;
  }

  .sidebar::-webkit-scrollbar,
  .sidebar .nav-label,
  .sidebar-note {
    display: none;
  }

  .nav-list {
    display: flex;
    width: max-content;
  }

  .nav-link {
    min-height: 2.5rem;
    white-space: nowrap;
  }

  .nav-link--active {
    box-shadow: inset 0 -3px var(--leaf-600);
  }

  .main-content {
    padding: 1.5rem 1rem 2.5rem;
  }

  .search-form__row {
    align-items: stretch;
    flex-direction: column;
  }

  .filter-selects,
  .filter-selects label {
    width: 100%;
  }

  .page-heading {
    display: block;
  }

  .page-heading .status {
    margin-top: 1rem;
  }

  .collection-panel {
    min-height: 23rem;
    border-radius: var(--radius-medium);
  }

  .bookmark-card {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .bookmark-card__heading,
  .bookmark-card__meta {
    align-items: start;
    flex-direction: column;
  }

  .bookmark-card__actions {
    grid-column: 2;
    justify-content: start;
  }

  .site-footer {
    text-align: center;
  }
}

@media (max-width: 390px) {
  .site-header {
    padding-inline: 0.75rem;
  }

  .brand strong {
    font-size: 1rem;
  }

  .brand-mark {
    width: 2.1rem;
    height: 2.1rem;
  }

  .collection-panel__header {
    align-items: start;
    flex-direction: column;
  }

  .dialog {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto;
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
    transition-duration: 0.01ms;
  }
}

@media (prefers-contrast: more) {
  :root {
    --line: #827d70;
    --line-strong: #615d53;
  }
}

