  .page-heading .status {
    margin-top: 1rem;
  }

  .collection-panel {
    min-height: 23rem;
    border-radius: var(--radius-medium);
  }

  .bookmark-card {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .bookmark-card__heading,
  .bookmark-card__meta {
    align-items: start;
    flex-direction: column;
  }

  .bookmark-card__actions {
    grid-column: 2;
    justify-content: start;
  }

  .site-footer {
    text-align: center;
  }
}

@media (max-width: 390px) {
  .site-header {
    padding-inline: 0.75rem;
  }

  .brand strong {
    font-size: 1rem;
  }

  .brand-mark {
    width: 2.1rem;
    height: 2.1rem;
  }

  .collection-panel__header {
    align-items: start;
    flex-direction: column;
  }

  .dialog {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto;
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
    transition-duration: 0.01ms;
  }
}

@media (prefers-contrast: more) {
  :root {
    --line: #827d70;
    --line-strong: #615d53;
  }
}

