import { Button, Dialog, IconPlaceholder, Status } from "../../components";
import type { Bookmark } from "../../lib/api";

export interface BookmarkDetailProps {
  bookmark: Bookmark;
  onClose: () => void;
  editing?: boolean;
}

function displayDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(value));
}

export function BookmarkDetail({ bookmark, onClose, editing = false }: BookmarkDetailProps) {
  return (
    <Dialog
      open
      title={bookmark.title}
      description={bookmark.description || "No description has been added."}
      onClose={onClose}
      footer={
        <>
          <Button variant="quiet" onClick={onClose}>
            Close
          </Button>
          <a
            className="button button--primary button--medium"
            href={bookmark.address}
            target="_blank"
            rel="noopener noreferrer"
          >
            <span>Open destination ↗</span>
          </a>
        </>
      }
    >
      <div className="bookmark-detail">
        {editing ? <Status tone="warning">This bookmark is ready to edit.</Status> : null}
        <div className="bookmark-detail__identity">
          {bookmark.iconUrl ? (
            <img
              src={bookmark.iconUrl}
              alt={`Site icon for ${bookmark.title}`}
              width="48"
              height="48"
            />
          ) : (
            <IconPlaceholder label={`No site icon for ${bookmark.title}`} size="large" />
          )}
          <p>{bookmark.address}</p>
        </div>
        <dl className="bookmark-detail__facts">
          <div>
            <dt>Reading</dt>
            <dd>{bookmark.unread ? "Read Later" : "Read"}</dd>
          </div>
          <div>
            <dt>Favorite</dt>
            <dd>{bookmark.favorite ? "Yes" : "No"}</dd>
          </div>
          <div>
            <dt>Created</dt>
            <dd>{displayDate(bookmark.createdAt)}</dd>
          </div>
          <div>
            <dt>Updated</dt>
            <dd>{displayDate(bookmark.updatedAt)}</dd>
          </div>
        </dl>
        {bookmark.tags.length ? (
          <ul className="tag-list" aria-label="Tags">
            {bookmark.tags.map((tag) => (
              <li key={tag.id}>{tag.name}</li>
            ))}
          </ul>
        ) : null}
      </div>
    </Dialog>
  );
}

