function displayDate(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(value));
}

export function BookmarkDetail({
  bookmark,
  onClose,
  editing = false,
  client,
  onEdit,
  onCancelEdit,
  onUpdated,
  onDuplicate,
  onRequestDelete,
